import sys,os,json,unittest,pathlib
if not __debug__ or sys.flags.optimize:raise RuntimeError("unoptimized Python required")
root=pathlib.Path(sys.argv[1]);sys.path.insert(0,str(root))
suite=unittest.TestLoader().discover(str(root),pattern="test_package_*.py")
def names(s):
 for t in s:
  if isinstance(t,unittest.TestSuite):yield from names(t)
  else:yield t.id()
selected=list(names(suite))
EXPECTED=["test_package_binding.BindingTests.test_digest_syntax_and_duplicate_keys_refused","test_package_binding.BindingTests.test_exact_committed_binding_accepted","test_package_binding.BindingTests.test_exact_member_set_required","test_package_binding.BindingTests.test_exact_schema_fields_and_integer_required","test_package_binding.BindingTests.test_repository_commit_and_abi_identity_strict","test_package_candidate.CandidateTests.test_actual_gate_rejects_bad_structure_and_noncanonical_declaration","test_package_candidate.CandidateTests.test_actual_gate_rejects_unknown_import_and_wrong_declaration","test_package_candidate.CandidateTests.test_actual_gate_zero_import_and_exact_set","test_package_candidate.CandidateTests.test_changed_core_source_refused","test_package_candidate.CandidateTests.test_core_source_drift_before_emission_refused","test_package_candidate.CandidateTests.test_existing_output_is_preserved","test_package_candidate.CandidateTests.test_generator_cannot_change_manifest_contract","test_package_candidate.CandidateTests.test_generator_cannot_change_validated_elf","test_package_candidate.CandidateTests.test_hidden_loader_export_is_not_silently_accepted","test_package_candidate.CandidateTests.test_import_refusal_precedes_mapping_and_emission","test_package_candidate.CandidateTests.test_internal_getter_refused_by_actual_entry_contract","test_package_candidate.CandidateTests.test_mapping_refusal_precedes_emission","test_package_candidate.CandidateTests.test_original_path_change_cannot_change_emitted_snapshot","test_package_candidate.CandidateTests.test_producer_emits_exact_validated_bytes_and_false_authority","test_package_candidate.CandidateTests.test_source_and_tooling_pins_fail_closed","test_package_candidate.CandidateTests.test_structural_rejection_precedes_python_elf_and_mapping","test_package_candidate.ConfigTests.test_config_accepts_exact_bounded_composition","test_package_candidate.ConfigTests.test_config_refuses_bool_overflow_and_zero_cleanup_reserve","test_package_candidate.ConfigTests.test_config_refuses_identity_path_and_authority_extensions","test_package_candidate.ConfigTests.test_metadata_candidate_mode_is_explicit_not_authority","test_package_mapping.MappingTests.test_abs_does_not_authorize_ordinary_mapping","test_package_mapping.MappingTests.test_abs_exception_boundaries_and_evidence","test_package_mapping.MappingTests.test_alignment_padding_budget","test_package_mapping.MappingTests.test_all_rela_and_exact_span","test_package_mapping.MappingTests.test_global_function_full_extent_and_local_nonexport","test_package_mapping.MappingTests.test_hidden_functions_and_objects_are_actual_exports","test_package_mapping.MappingTests.test_import_and_definition_relocations","test_package_mapping.MappingTests.test_internal_shapes_and_budget","test_package_mapping.MappingTests.test_none_and_repeated_mutating_sites","test_package_mapping.MappingTests.test_ordinary_and_exact_exports","test_package_mapping.MappingTests.test_overlap_and_bad_alignment","test_package_mapping.MappingTests.test_relative_null_mapped_bss_and_abs","test_package_mapping.MappingTests.test_zero_size_duplicate_is_refused"]
if sorted(selected)!=EXPECTED:raise RuntimeError("exact case selection changed")
if len(selected)!=38 or len(set(selected))!=38:raise RuntimeError("expected exactly38 distinct cases")
class Result(unittest.TextTestResult):
 def __init__(self,*args,**kw):super().__init__(*args,**kw);self.passed=[]
 def addSuccess(self,t):self.passed.append(t.id());super().addSuccess(t)
result=unittest.TextTestRunner(verbosity=2,resultclass=Result).run(suite)
report={"expected":len(selected),"selected":selected,"run":result.testsRun,"passed":result.passed,"failures":[[t.id(),s] for t,s in result.failures],"errors":[[t.id(),s] for t,s in result.errors],"skipped":[[t.id(),s] for t,s in result.skipped]}
pathlib.Path(os.environ["RISC_TEST_OUTPUT"]).write_text(json.dumps(report,sort_keys=True,indent=2)+"\n")
sys.exit(0 if result.wasSuccessful() and result.testsRun==38 and not result.skipped else 1)
